export function validatePostAttemptFeedbackWordingPolicy(options = {}) {
  const opts = optionsFrom(options);
  const policyArtifactRecord = isRecord(opts.policyArtifact);
  const upstreamRecord = isRecord(opts.upstream);
  const policyArtifact = policyArtifactRecord ? opts.policyArtifact : {};
  const upstream = upstreamRecord ? opts.upstream : {};
  const fixtures = arrayFrom(policyArtifact.fixtures);
  const errors = [];

  if (Array.isArray(upstream?.diagnostics)) {
    errors.push(...upstream.diagnostics);
  }

  if (!isRecord(options)) errors.push('options_record_required');
  if (!policyArtifactRecord) errors.push('policy_artifact_required');
  if (!upstreamRecord) errors.push('upstream_required');
  if (policyArtifactRecord && !Array.isArray(opts.policyArtifact.fixtures)) {
    errors.push('fixtures_array_required');
  }

  const fixtureIds = fixtures.map((fixture) => fixture?.fixture_id).filter(Boolean);
  const allRequiredFixturesPresent =
    REQUIRED_FIXTURE_IDS.every((id) => fixtureIds.includes(id)) &&
    fixtureIds.length === REQUIRED_FIXTURE_IDS.length;
  if (!allRequiredFixturesPresent) errors.push('required_feedback_wording_fixtures_missing');

  const wordingTiers = arrayFrom(policyArtifact.wording_tiers);
  if (policyArtifactRecord && policyArtifact.wording_tiers !== undefined && !Array.isArray(policyArtifact.wording_tiers)) {
    errors.push('wording_tiers_array_required');
  }
  const tiersReported =
    wordingTiers.length > 0 &&
    WORDING_TIERS.every((tier) => wordingTiers.includes(tier)) &&
    fixtures.every((fixture) => WORDING_TIERS.includes(fixture?.policy?.feedback_tier));
  if (!tiersReported) errors.push('wording_tiers_not_reported');

  const claimFields = arrayFrom(policyArtifact.claim_fields);
  if (policyArtifactRecord && policyArtifact.claim_fields !== undefined && !Array.isArray(policyArtifact.claim_fields)) {
    errors.push('claim_fields_array_required');
  }
  const claimFieldsValid =
    claimFields.length > 0 &&
    CLAIM_FIELDS.every((field) => claimFields.includes(field));
  if (!claimFieldsValid) errors.push('claim_fields_invalid');

  const bannedWordingPatterns = arrayFrom(policyArtifact.banned_wording_patterns);
  if (policyArtifactRecord && policyArtifact.banned_wording_patterns !== undefined && !Array.isArray(policyArtifact.banned_wording_patterns)) {
    errors.push('banned_wording_patterns_array_required');
  }
  const bannedWordingPatternsValid =
    bannedWordingPatterns.length > 0 &&
    BANNED_WORDING_PATTERNS.every((pattern) => bannedWordingPatterns.includes(pattern.id));
  if (!bannedWordingPatternsValid) errors.push('banned_wording_patterns_invalid');

  const dependsOnIssues = arrayFrom(policyArtifact.depends_on_issues);
  if (policyArtifactRecord && policyArtifact.depends_on_issues !== undefined && !Array.isArray(policyArtifact.depends_on_issues)) {
    errors.push('depends_on_issues_array_required');
  }
  const dependsOnIssuesValid =
    dependsOnIssues.length > 0 &&
    DEPENDS_ON_ISSUES.every((issue) => dependsOnIssues.includes(issue));
  if (!dependsOnIssuesValid) errors.push('depends_on_issues_invalid');
